        "ev": "지상으로 나와 메트로 M6 Montparnasse-Bienvenue로 이동. 몽파르나스 타워(Tour Montparnasse, €18/인) 56층 전망대에 오르면 파리 전체가 발아래 펼쳐진다 — 에펠탑을 포함한 파리 전경이 한눈에 보이는 이 전망대가 \"에펠탑 뷰의 최고 포인트\"인 이유는, 이곳에선 몽파르나스 타워가 시야에 들어오지 않기 때문이다. 일몰 시간에 맞춰 올라가 저녁은 주변 르 셀렉트(Le Select, 1925년) 브라스리에서.",
        "tip": "카타콩브는 현장 판매 없음 — catacombes.paris.fr 에서 사전 예약 필수(최소 2주 전 권장, 입장 시간 엄수). 팡테옹과 카타콩브는 거리상 30분이므로 예약 시간을 역산해서 팡테옹·클뤼니 관람 시간을 설계해야 한다. 몽파르나스 타워는 현재 리모델링 이후 운영 재개 여부 확인 필요 — 2027년 1월 기준 공식 사이트(tourmontparnasse56.com) 사전 확인.",
